    /// Moves the completed task's <c>.relay/&lt;taskId&gt;/</c> directory to
    /// <c>.relay/completed/&lt;taskId&gt;-&lt;runId&gt;/</c> so a future
    /// same-name task starts with a clean slate. Best-effort: failures are
    /// silently swallowed (the run already committed successfully).
    /// </summary>
    private static void ArchiveCompletedRelayDir(
        string rootPath,
        string taskId,
        string taskDirectory,
        string runId)
    {
        try
        {
            if (!Directory.Exists(taskDirectory))
                return;
            var relayDir = Path.Combine(rootPath, ".relay");
            var completedDir = Path.Combine(relayDir, "completed");
            Directory.CreateDirectory(completedDir);
            var baseArchivePath = Path.Combine(completedDir, $"{taskId}-{runId}");
            var archivePath = baseArchivePath;
            var suffix = 2;
            while (Directory.Exists(archivePath))
            {
                archivePath = $"{baseArchivePath}-{suffix}";
                suffix++;
            }
            Directory.Move(taskDirectory, archivePath);
        }
        catch
        {
            // Best-effort: the run already committed successfully.
        }
    }
